function formatarCompetenciaFolha(valor?: string) {
  if (!valor) return "";
  const match = valor.match(/^(\d{4})-(\d{2})$/);
  if (match) return `${match[2]}/${match[1]}`;
  return valor;
}

function formatarDataPtBr(data = new Date()) {
  return data.toLocaleDateString("pt-BR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });
}

